(j.textures||[]).forEach((t,i)=>console.log('tex',i,JSON.stringify(t)));
(j.images||[]).forEach((im,i)=>{const bv=j.bufferViews[im.bufferView];const o=binOff+(bv.byteOffset||0);let w='',h='';
 if(im.mimeType==='image/png'){w=b.readUInt32BE(o+16);h=b.readUInt32BE(o+20);} else {let p=o+2;while(p<o+bv.byteLength){if(b[p]!==0xFF){p++;continue}const mk=b[p+1];const L=b.readUInt16BE(p+2);if(mk>=0xC0&&mk<=0xC3){h=b.readUInt16BE(p+5);w=b.readUInt16BE(p+7);break}p+=2+L;}}
 console.log('img',i,im.name,im.mimeType,bv.byteLength,w+'x'+h);});
// orphan checks
