const usedImg=new Set((j.textures||[]).map(t=>t.source));console.log('imgs',(j.images||[]).length,'used by tex',usedImg.size);
const usedTex=new Set();JSON.stringify(j.materials,(k,v)=>{if(v&&typeof v==='object'&&'index'in v&&k.endsWith('Texture'))usedTex.add(v.index);return v});console.log('tex',(j.textures||[]).length,'used',usedTex.size);
const usedMat=new Set(j.meshes.flatMap(m=>m.primitives.map(p=>p.material)));console.log('mats',j.materials.length,'used',usedMat.size);
const s=JSON.stringify(j);for(const k of ['62A','093','Object_12','Object_13','Material.004','Material.005','bien','plate','BIEN'])console.log('search',k,s.includes(k));
console.log('extensionsUsed',JSON.stringify(j.extensionsUsed));
EOF
